namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<div class="message-input">
    <textarea class="message-input__textarea"
              @bind="text"
              @bind:event="oninput"
              @onkeydown="HandleKeyDown"
              placeholder="@Placeholder"
              rows="2"></textarea>
    <button class="message-input__send-btn" @onclick="Submit" disabled="@string.IsNullOrWhiteSpace(text)">
        @ButtonLabel
    </button>
</div>

@code {
    private string text = string.Empty;

    [Parameter] public string Placeholder { get; set; } = "Type a message...";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Submit();
        }
    }

    private async Task Submit()
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        var content = text.Trim();
        text = string.Empty;
        await OnSubmit.InvokeAsync(content);
    }
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<div class="message-bubble" @onmouseenter="() => showActions = true" @onmouseleave="() => showActions = false">
    <div class="message-bubble__header">
        <span class="message-bubble__author">@Message.Author</span>
        <span class="message-bubble__time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-bubble__content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-bubble__reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="message-bubble__reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="message-bubble__thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount replies
        </button>
    }

    @if (showActions && ShowActions)
    {
        <div class="message-bubble__actions">
            <button class="message-bubble__action-btn" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)" title="Reply in thread">
                💬 Reply
            </button>
            <button class="message-bubble__action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">
                😀 React
            </button>
        </div>

        @if (showEmojiPicker)
        {
            <div class="message-bubble__emoji-picker">
                @foreach (var emoji in commonEmojis)
                {
                    <button class="message-bubble__emoji-btn" @onclick="() => SelectEmoji(emoji)">@emoji</button>
                }
            </div>
        }
    }
</div>

@code {
    private bool showActions;
    private bool showEmojiPicker;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🔥", "👀"];

    [Parameter, EditorRequired] public Services.Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public bool ShowActions { get; set; } = true;
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync(emoji);
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<div class="channel-item @(IsActive ? "channel-item--active" : "")" @onclick="() => OnSelect.InvokeAsync(Channel.Id)">
    <div class="channel-item__header">
        <span class="channel-item__name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="channel-item__badge">@Channel.UnreadCount</span>
        }
    </div>
    <div class="channel-item__description">@TruncateDescription(Channel.Description)</div>
</div>

@code {
    [Parameter, EditorRequired] public Services.Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<int> OnSelect { get; set; }

    private static string TruncateDescription(string desc)
        => desc.Length > 50 ? desc[..47] + "..." : desc;
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<aside class="channel-sidebar">
    <h3 class="channel-sidebar__title">Channels</h3>
    <div class="channel-sidebar__list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelect="OnChannelSelected" />
        }
    </div>
</aside>

@code {
    [Parameter] public List<Services.Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat
@inject IJSRuntime JS

<div class="message-list" @ref="scrollContainer" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="message-list__loading">Loading older messages...</div>
    }
    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ReplyCount="GetReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
    }
</div>

@code {
    private ElementReference scrollContainer;

    [Parameter] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId)
        => ThreadReplyCounts.GetValueOrDefault(messageId, 0);

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('.message-list').scrollTop");
        if (scrollTop < 50 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<section class="message-area">
    @if (Channel is not null)
    {
        <header class="message-area__header">
            <h2 class="message-area__channel-name"># @Channel.Name</h2>
            <p class="message-area__channel-desc">@Channel.Description</p>
        </header>

        <MessageList Messages="Messages"
                     ThreadReplyCounts="ThreadReplyCounts"
                     IsLoadingMore="IsLoadingMore"
                     OnLoadMore="OnLoadMore"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />

        <MessageInput Placeholder="@($"Message #{Channel.Name}")"
                      ButtonLabel="Send"
                      OnSubmit="OnSendMessage" />
    }
    else
    {
        <div class="message-area__empty">Select a channel to start chatting</div>
    }
</section>

@code {
    [Parameter] public Services.Channel? Channel { get; set; }
    [Parameter] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<aside class="thread-panel">
    <header class="thread-panel__header">
        <h3>Thread</h3>
        <button class="thread-panel__close-btn" @onclick="OnClose">✕</button>
    </header>

    @if (RootMessage is not null)
    {
        <div class="thread-panel__root-message">
            <MessageBubble Message="RootMessage" ShowActions="false" />
        </div>

        <div class="thread-panel__replies">
            @foreach (var reply in Replies)
            {
                <MessageBubble Message="reply" ShowActions="false" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread..."
                      ButtonLabel="Reply"
                      OnSubmit="OnSendReply" />
    }
</aside>

@code {
    [Parameter] public Services.Message? RootMessage { get; set; }
    [Parameter] public List<Services.Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
}

@page "/chat"
@using sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat
@using sv_1390ad55511b4319a99d9d2d6a74cee4.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "chat-layout--thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea Channel="activeChannel"
                 Messages="messages"
                 ThreadReplyCounts="threadReplyCounts"
                 IsLoadingMore="isLoadingMore"
                 OnLoadMore="LoadMoreMessages"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadReplies = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private int? selectedChannelId;
    private Channel? activeChannel;
    private Message? threadRootMessage;
    private bool threadOpen;
    private bool isLoadingMore;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        await ComputeThreadCounts();
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || activeChannel is null) return;
        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannel.Id, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            await ComputeThreadCounts();
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(activeChannel.Id, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
