@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<div class="channel-item @(IsActive ? "channel-item--active" : "")" @onclick="() => OnSelect.InvokeAsync(Channel.Id)">
    <div class="channel-item__header">
        <span class="channel-item__name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="channel-item__badge">@Channel.UnreadCount</span>
        }
    </div>
    <div class="channel-item__description">@TruncateDescription(Channel.Description)</div>
</div>

@code {
    [Parameter, EditorRequired] public Services.Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<int> OnSelect { get; set; }

    private static string TruncateDescription(string desc)
        => desc.Length > 50 ? desc[..47] + "..." : desc;
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat

<aside class="channel-sidebar">
    <h3 class="channel-sidebar__title">Channels</h3>
    <div class="channel-sidebar__list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelect="OnChannelSelected" />
        }
    </div>
</aside>

@code {
    [Parameter] public List<Services.Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

@namespace sv_1390ad55511b4319a99d9d2d6a74cee4.Components.Chat
@inject IJSRuntime JS

<div class="message-list" @ref="scrollContainer" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="message-list__loading">Loading older messages...</div>
    }
    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ReplyCount="GetReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
    }
</div>

@code {
    private ElementReference scrollContainer;

    [Parameter] public List<Services.Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId)
        => ThreadReplyCounts.GetValueOrDefault(messageId, 0);

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('.message-list').scrollTop");
        if (scrollTop < 50 && !IsLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

