arguments.file_text:
/* Chat Layout */
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout--thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
.channel-sidebar {
    background: #2c2f33;
    color: #dcddde;
    padding: 1rem;
    overflow-y: auto;
    border-right: 1px solid #202225;
}

.channel-sidebar__title {
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #8e9297;
    margin-bottom: 0.75rem;
}

.channel-sidebar__list {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

/* Channel Item */
.channel-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    cursor: pointer;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #34373c;
}

.channel-item--active {
    background: #393c43;
    color: #fff;
}

.channel-item__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.channel-item__name {
    font-weight: 500;
    font-size: 0.9375rem;
}

.channel-item__badge {
    background: #ed4245;
    color: #fff;
    font-size: 0.75rem;
    font-weight: 700;
    padding: 0.125rem 0.375rem;
    border-radius: 9999px;
    min-width: 1.25rem;
    text-align: center;
}

.channel-item__description {
    font-size: 0.75rem;
    color: #8e9297;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Message Area */
.message-area {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: #36393f;
    color: #dcddde;
}

.message-area__header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #202225;
    flex-shrink: 0;
}

.message-area__channel-name {
    font-size: 1.125rem;
    font-weight: 600;
    color: #fff;
    margin: 0;
}

.message-area__channel-desc {
    font-size: 0.8125rem;
    color: #8e9297;
    margin: 0.25rem 0 0;
}

.message-area__empty {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #8e9297;
    font-size: 1.125rem;
}

/* Message List */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.message-list__loading {
    text-align: center;
    padding: 0.5rem;
    color: #8e9297;
    font-size: 0.8125rem;
}

/* Message Bubble */
.message-bubble {
    position: relative;
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    transition: background 0.1s;
}

.message-bubble:hover {
    background: #32353b;
}

.message-bubble__header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
}

.message-bubble__author {
    font-weight: 600;
    color: #fff;
    font-size: 0.9375rem;
}

.message-bubble__time {
    font-size: 0.75rem;
    color: #72767d;
}

.message-bubble__content {
    margin-top: 0.25rem;
    line-height: 1.4;
    word-wrap: break-word;
}

.message-bubble__reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.375rem;
}

.message-bubble__reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    background: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 0.125rem 0.375rem;
    font-size: 0.8125rem;
    cursor: pointer;
    transition: border-color 0.15s;
}

.message-bubble__reaction-badge:hover {
    border-color: #5865f2;
}

.message-bubble__thread-link {
    background: none;
    border: none;
    color: #00aff4;
    font-size: 0.8125rem;
    cursor: pointer;
    padding: 0.25rem 0;
    margin-top: 0.25rem;
}

.message-bubble__thread-link:hover {
    text-decoration: underline;
}

.message-bubble__actions {
    position: absolute;
    top: -0.75rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 2px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.message-bubble__action-btn {
    background: none;
    border: none;
    color: #b9bbbe;
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    border-radius: 3px;
    cursor: pointer;
}

.message-bubble__action-btn:hover {
    background: #40444b;
    color: #fff;
}

.message-bubble__emoji-picker {
    position: absolute;
    top: -2.5rem;
    right: 0.5rem;
    display: flex;
    gap: 2px;
    background: #2f3136;
    border: 1px solid #40444b;
    border-radius: 4px;
    padding: 4px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.message-bubble__emoji-btn {
    background: none;
    border: none;
    font-size: 1.25rem;
    cursor: pointer;
    padding: 0.25rem;
    border-radius: 3px;
}

.message-bubble__emoji-btn:hover {
    background: #40444b;
}

/* Message Input */
.message-input {
    display: flex;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border-top: 1px solid #202225;
    flex-shrink: 0;
}

.message-input__textarea {
    flex: 1;
    background: #40444b;
    border: none;
    border-radius: 8px;
    color: #dcddde;
    padding: 0.625rem 1rem;
    font-size: 0.9375rem;
    resize: none;
    font-family: inherit;
}

.message-input__textarea::placeholder {
    color: #72767d;
}

.message-input__textarea:focus {
    outline: none;
    box-shadow: 0 0 0 2px #5865f2;
}

.message-input__send-btn {
    background: #5865f2;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 0.625rem 1.25rem;
    font-weight: 600;
    cursor: pointer;
